using System.IO;
using System.IO.Compression;
using System.Text;
using System.Text.Json.Nodes;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace GeMMeElec;

internal static class DeliveryTests
{
    public static void Run(Action<string,Action> test,Action<bool,string> assert,Action<Action> reject,string dir)
    {
        test("Transactions locales : validation avant mutation, identité du JSON et coalescence",()=>{
            var e=new Editor();var a=e.AddComponent("coil",200,200);var b=e.AddComponent("coil",400,400);e.Connect(new(a.Id,"A2"),new(b.Id,"A1"));e.Change(()=>{a.Description="Équipement \"été\" avec {crochets} [ports] et chemin C:\\tests";e.Project.CustomFields["JSON"]="\"sheets\":[{}]";});string path=Path.Combine(dir,"self-test-local-properties.gemelec");e.Save(path);string before=e.ExportSnapshot;
            e.SetComponentField(a.Id,"description","Commande été");e.SetComponentField(a.Id,"description","Commande été 24 V");assert(e.ExportSnapshot==ProjectStore.Serialize(e.Project)&&e.Dirty,"Cache différent du JSON");string after=e.ExportSnapshot;reject(()=>e.SetComponentField(a.Id,"X","-1"));reject(()=>e.SetComponentField(a.Id,"X","NaN"));reject(()=>e.SetComponentField(a.Id,"rotation","45"));reject(()=>e.SetComponentField(a.Id,"port:absent","1"));reject(()=>e.SetComponentField(a.Id,"symbol","terminal"));assert(e.ExportSnapshot==after&&ProjectStore.Serialize(e.Project)==after,"Mutation invalide partielle");e.Undo();assert(e.ExportSnapshot==before&&!e.Dirty,"Coalescence ou état enregistré perdu");e.Redo();assert(e.ExportSnapshot==after,"Rétablissement local");e.SetComponentField(a.Id,"X","250,5");assert(e.Sheet.Wires[0].Route(e.Sheet)[0].X==250.5,"Fil détaché");e.Save(path);assert(ProjectStore.Serialize(ProjectStore.Load(path))==e.ExportSnapshot,"Relecture différente");
        });
        test("Transactions locales : familles interfolios et mélange avec historique structurel",()=>{
            var e=new Editor();var coil=e.AddComponent("coil",200,200);e.AddSheet("Contacts");var contact=e.AddComponent("contact_no",400,400);e.AssociateContact(contact.Id,coil.Id);string before=e.ExportSnapshot;e.SetComponentField(contact.Id,"tag","KM-Été");ProjectStore.ValidateStructure(e.Project);string after=e.ExportSnapshot;assert(after==ProjectStore.Serialize(e.Project)&&e.Project.Sheets[0].Components[0].Tag=="KM-Été","Famille partiellement renommée");e.AddSheet("Réserve");e.Undo();assert(e.ExportSnapshot==after,"Undo structurel");e.Undo();assert(e.ExportSnapshot==before,"Undo local interfolios");e.Redo();assert(e.ExportSnapshot==after,"Redo local interfolios");e.Redo();assert(e.Project.Sheets.Count==3&&e.ExportSnapshot==ProjectStore.Serialize(e.Project),"Mélange des historiques");
        });
        test("Récupération : copies bornées, intégrité et fichier de travail préservé",()=>{
            var e=new Editor();e.AddComponent("coil",200,200);string source=Path.Combine(dir,"self-test-recovery-source.gemelec");e.Save(source);byte[] original=File.ReadAllBytes(source);string folder=Path.Combine(dir,"self-test-recovery-"+Guid.NewGuid().ToString("N"));RecoveryInfo? last=null;for(int i=0;i<4;i++){e.SetComponentField(e.Sheet.Components[0].Id,"description","Copie "+i);last=RecoveryStore.Write(e.ExportSnapshot,e.Project.Id,e.Project.Title,source,e.Sheet.Id,2,folder);}assert(RecoveryStore.List(folder).Count==2,"Copies non bornées");var restored=RecoveryStore.Read(last!.File);assert(ProjectStore.Serialize(restored.Project)==e.ExportSnapshot&&original.SequenceEqual(File.ReadAllBytes(source)),"Copie perdue ou fichier écrasé");var other=new Editor();other.ImportProject(restored.Project);assert(other.Dirty&&other.FilePath is null,"Restauration associée au fichier original");reject(()=>RecoveryStore.Write(e.ExportSnapshot,e.Project.Id,"","","",0,folder));
            using(var archive=ZipFile.Open(last.File,ZipArchiveMode.Update)){archive.GetEntry("project.gemelec")!.Delete();using var writer=new StreamWriter(archive.CreateEntry("project.gemelec").Open());writer.Write("{}");}reject(()=>RecoveryStore.Read(last.File));assert(original.SequenceEqual(File.ReadAllBytes(source)),"Copie altérée écrasant la source");
        });
        test("Gabarits : contenus remappés, plans, associations et bibliothèque indépendante",()=>{
            var e=new Editor();var coil=e.AddComponent("coil",200,200);var terminal=e.AddComponent("terminal",400,200);e.Connect(new(coil.Id,"A2"),new(terminal.Id,"1"));var strip=new TerminalStrip{Name="X1",Terminals=[new(){ComponentId=terminal.Id,Number="1"}]};e.PutTerminalStrip(strip);e.PutCabinet(new(){Id="A1",Items=[new(){ComponentId=coil.Id,Width=45,Height=80,X=20,Y=20}]});e.GenerateTerminalPlan(strip.Id);e.GenerateCabinetPlan("A1");e.AddSheet("Contacts");var contact=e.AddComponent("contact_no",400,400);e.AssociateContact(contact.Id,coil.Id);e.Change(()=>{e.Project.ZoneColumns=16;});string before=e.ExportSnapshot;var full=ProjectTemplates.Instantiate(e.Project,"Nouvelle armoire",true);assert(full.Id!=e.Project.Id&&!full.Sheets.Any(s=>e.Project.Sheets.Any(old=>old.Id==s.Id))&&new CoilContacts(full).Contacts(full.Sheets[0].Components[0].Id).Count==1,"Identités non remappées");assert(full.TerminalStrips[0].Terminals[0].ComponentId==full.Sheets[0].Components[1].Id&&full.Cabinets[0].Items[0].ComponentId==full.Sheets[0].Components[0].Id,"Affectations orphelines");var empty=ProjectTemplates.Instantiate(e.Project,"Vide",false);assert(empty.ZoneColumns==16&&empty.Sheets.Count==2&&empty.Sheets.All(s=>s.Components.Count+s.Wires.Count+s.Notes.Count==0)&&empty.Cabinets.Count+empty.TerminalStrips.Count==0,"Gabarit vide incomplet");full.Sheets[0].Components[0].Tag="CHANGÉ";assert(e.ExportSnapshot==before,"Gabarit partageant la source");string path=Path.Combine(dir,"self-test-template.gemtemplate");ProjectTemplates.Save(e.Project,path,true,new(){Colors=[new("Personnalisée","#AA1122")],WireColor="#AA1122"});var loaded=ProjectTemplates.Load(path);assert(loaded.IncludeObjects&&loaded.Project.Sheets.Count==e.Project.Sheets.Count&&loaded.Palette?.Colors.Single().Color=="#AA1122","Gabarit ou palette non relu");reject(()=>ProjectTemplates.Save(e.Project,path+".json",true));
        });
        test("Présentation : aperçu sur copie, réglages individuels, annulation et persistance",()=>{
            var e=new Editor();var a=e.AddComponent("coil",200,200);var b=e.AddComponent("coil",500,500);var wire=e.Connect(new(a.Id,"A2"),new(b.Id,"A1"),number:"IND",numberIndependent:true,color:"#D32F2F",thickness:3);e.Change(()=>a.TagPlacement.FontSize=24);string before=e.ExportSnapshot;var copy=ProjectStore.Deserialize(before);var style=ProjectPresentation.Preset("Noir");Presentation.Apply(copy,style);assert(e.ExportSnapshot==before&&copy.Sheets[0].Components[0].TagPlacement.FontSize==24&&copy.Sheets[0].Wires[0].Color=="#D32F2F","Aperçu ou réglages individuels altérés");e.Change(()=>Presentation.Apply(e.Project,style));assert(Drawing.Scene(e.Project,e.Sheet).Any(i=>i.Color=="#000000")&&wire.Number=="IND"&&a.X==200,"Style modifiant les données électriques");string path=Path.Combine(dir,"self-test-presentation.gemelec");e.Save(path);assert(ProjectStore.Load(path).Presentation.Name=="Noir","Style non persistant");e.Undo();assert(e.ExportSnapshot==before,"Présentation non annulable");style.PreserveIndividual=false;e.Change(()=>Presentation.Apply(e.Project,style));assert(e.Sheet.Wires[0].Color=="#000000"&&e.Sheet.Components[0].TagPlacement.FontSize==16,"Uniformisation complète refusée");reject(()=>e.Change(()=>Presentation.Apply(e.Project,new(){TagSize=1})));
        });
        test("PDF navigable : sommaire, reports et références réciproques",()=>{
            var e=new Editor();var coil=e.AddComponent("coil",350,350);var report=e.AddComponent("folio_next",700,350);e.ConfigureReference(report.Id,"LIAISON","pair",0,false);e.AddSheet("Contacts été");var contact=e.AddComponent("contact_no",350,350);e.AssociateContact(contact.Id,coil.Id);var target=e.AddComponent("folio_previous",700,350);e.ConfigureReference(target.Id,"LIAISON","pair",1,false);string before=e.ExportSnapshot;var pages=PdfNavigation.Pages(e.Project);assert(pages.Count==3&&pages[0].Links.Count==2&&pages.Skip(1).Sum(s=>s.Links.Count)==4,"Navigation incomplète");Export.Pdf(e.Project,Path.Combine(dir,"self-test-navigable.pdf"));string pdf=Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(dir,"self-test-navigable.pdf")));assert(pdf.Contains("/Type /Outlines")&&pdf.Contains("/Subtype /Link")&&pdf.Contains("/Type /Pages /Count 3")&&e.ExportSnapshot==before,"PDF ou projet modifié");e.Change(()=>e.Project.PdfOptions=new(){Contents=false,Bookmarks=false,Links=false});Export.Pdf(e.Project,Path.Combine(dir,"self-test-no-navigation.pdf"));pdf=Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(dir,"self-test-no-navigation.pdf")));assert(!pdf.Contains("/Type /Outlines")&&!pdf.Contains("/Subtype /Link")&&pdf.Contains("/Type /Pages /Count 2"),"Options PDF ignorées");
        });
        test("PDF navigable : pagination du sommaire et migration de six versions",()=>{
            var p=EditorBenchmark.Fixture(100);p.Title=string.Join(' ',Enumerable.Repeat("Projet très long",100));var pages=PdfNavigation.Pages(p);var contents=pages.Where(s=>s.Sheet.Id.StartsWith("pdf-contents-")).ToList();assert(contents.Count>=3&&contents.Sum(c=>c.Links.Count)==100&&contents.All(c=>c.Scene.All(i=>i.Kind!="text"||i.Y+i.Size<=950)),"Sommaire tronqué");var e=new Editor();for(int v=1;v<7;v++){var old=JsonNode.Parse(e.ExportSnapshot)!;old["version"]=v;old.AsObject().Remove("pdfOptions");old.AsObject().Remove("presentation");var loaded=ProjectStore.Deserialize(old.ToJsonString());assert(loaded.Version==7&&!loaded.PdfOptions.Contents&&loaded.PdfOptions.Bookmarks,"Migration ajoutant une page aux anciens projets");}
        });
        test("PDF navigable : identité du sommaire distincte des folios du projet",()=>{var p=new Project();p.Sheets[0].Id="pdf-contents-0";ProjectStore.ValidateStructure(p);var pages=PdfNavigation.Pages(p);assert(pages.Select(s=>s.Sheet.Id).Distinct().Count()==2&&pages[0].Links[0].TargetSheetId==p.Sheets[0].Id,"Collision d’identité du sommaire");Export.Pdf(p,Path.Combine(dir,"self-test-contents-identity.pdf"));});
        test("Numérotation locale : conflit avec un réseau situé dans un folio ultérieur",()=>{
            var e=new Editor();var first=e.Sheet;var a=e.AddComponent("coil",200,200);var b=e.AddComponent("coil",400,400);e.Connect(new(a.Id,"A2"),new(b.Id,"A1"),number:"OLD");e.AddSheet("Autre");a=e.AddComponent("coil",200,200);b=e.AddComponent("coil",400,400);e.Connect(new(a.Id,"A2"),new(b.Id,"A1"),number:"W1");var plan=AutoNumbering.Preview(e.Project,new(){Scope="wires",SheetId=first.Id});assert(!plan.CanApply&&plan.Changes.Any(c=>c.Status=="Conflit"),"Collision avec le réseau non sélectionné");
        });
        test("Dialogs de livraison : présentation, récupération, gabarit et PDF hors écran",()=>{
            string? old=Environment.GetEnvironmentVariable("GEMMEELEC_TEST_SESSION");Environment.SetEnvironmentVariable("GEMMEELEC_TEST_SESSION","1");var window=new MainWindow();int probes=0;try{window.Editor.AddComponent("coil",300,300);window.DocumentTestProbe=dialog=>{probes++;var root=(FrameworkElement)dialog.Content;root.Measure(new(1100,740));root.Arrange(new(0,0,1100,740));root.UpdateLayout();var image=new RenderTargetBitmap(1100,740,96,96,PixelFormats.Pbgra32);image.Render(root);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(Path.Combine(dir,"apercu-livraison-"+probes+".png"));png.Save(file);};foreach(string command in new[]{"presentation","recovery","templateSave","pdfOptions"})window.WorkspaceCommandForTest(command).Execute(null,window);assert(probes==4,"Boîte de dialogue inaccessible");}finally{window.DocumentTestProbe=null;window.DisposeTestBridge();Environment.SetEnvironmentVariable("GEMMEELEC_TEST_SESSION",old);}
        });
    }
}
